window.NARRATION = {"ci_a": {"dur": 22.72, "text": "Pressure shows how you actually lead. This is where you start to see the gap between instinct and intention. Take about 30 seconds on each of these. Write what actually went on inside you, rather than what you think should have happened. Only you can see what you write, and it's saved here so you can come back to it. Select Save on each one as you go, then select Next.", "sents": [[0.03, "Pressure shows how you actually lead.", 0], [2.93, "This is where you start to see the gap between instinct and intention.", 0], [7.35, "Take about 30 seconds on each of these.", 1], [9.97, "Write what actually went on inside you, rather than what you think should have happened.", 1], [14.69, "Only you can see what you write, and it's saved here so you can come back to it.", 1], [19.05, "Select Save on each one as you go, then select Next.", 2]], "v": "k1", "cues": [0.03, 7.35, 19.05]}, "ci_b": {"dur": 10.8, "text": "Now look at what you wrote and pick the pattern that's closest to it. There's no right answer. Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", "sents": [[0.01, "Now look at what you wrote and pick the pattern that's closest to it.", 0], [3.75, "There's no right answer.", 1], [5.23, "Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", 1]], "v": "k1", "cues": [0.01, 3.75]}, "ci_c": {"dur": 20.08, "text": "Now run the Foundation Reset. Say your five words, the ones you saved on the Foundation Reset screen. Ask yourself for two next-best steps. Pick the one you'll take in the next ten minutes. Then take one breath and answer the anchor on the last card. It takes about a minute and works best standing up, so do it now before you move on.", "sents": [[0, "Now run the Foundation Reset.", 0], [2.15, "Say your five words, the ones you saved on the Foundation Reset screen.", 1], [6.37, "Ask yourself for two next-best steps.", 1], [9.07, "Pick the one you'll take in the next ten minutes.", 1], [11.71, "Then take one breath and answer the anchor on the last card.", 1], [15.41, "It takes about a minute and works best standing up, so do it now before you move on.", 2]], "v": "k1", "cues": [0, 2.15, 15.41]}, "kc_retry": {"dur": 3.68, "text": "Not quite. Have another look, then try again.", "sents": [[0.05, "Not quite.", 0], [1.45, "Have another look, then try again.", 0]], "v": "v4l", "cues": [0.05]}, "n_1_0": {"dur": 9.76, "text": "Lesson 1 is about where you start. You'll spend about 35 minutes here, then complete one core rep in your Playbook during the week. Select Start Lesson.", "sents": [[0, "Lesson 1 is about where you start.", 0], [2.77, "You'll spend about 35 minutes here, then complete one core rep in your Playbook during the week.", 1], [8.23, "Select Start Lesson.", 1]], "v": "k1", "cues": [0, 2.77]}, "n_1_1": {"dur": 9.04, "text": "Read this moment, and picture yourself in it. In moments like this, you lead from what you've practiced, and that's what this season works on.", "sents": [[0.01, "Read this moment, and picture yourself in it.", 0], [3.41, "In moments like this, you lead from what you've practiced, and that's what this season works on.", 1]], "v": "v4l", "cues": [0.01, 3.41]}, "n_1_10": {"dur": 8.96, "text": "Back to Thursday at 4:40 p.m., with the plan due at 6 p.m. Pick the move you'd make, and you'll hear where it leads. You can try the other one afterward.", "sents": [[0, "Back to Thursday at 4:40 p.m., with the plan due at 6 p.m.", 0], [4.51, "Pick the move you'd make, and you'll hear where it leads.", 1], [7.41, "You can try the other one afterward.", 1]], "v": "k1", "cues": [0, 4.51]}, "n_1_10_o0": {"dur": 12.0, "text": "Answering emails until six feels productive, and under pressure, it's a normal reaction. It isn't a system, though, so tomorrow looks exactly like today. Try the other option to compare.", "sents": [[0.03, "Answering emails until six feels productive, and under pressure, it's a normal reaction.", 0], [5.87, "It isn't a system, though, so tomorrow looks exactly like today.", 0], [10.27, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.03]}, "n_1_10_o1": {"dur": 14.48, "text": "Take three minutes to name the one outcome that matters, then work back from it. That's the rep. By six, your manager needs your direction, not every detail, so share where you're heading and use their feedback to align before you fill in the rest.", "sents": [[0.01, "Take three minutes to name the one outcome that matters, then work back from it.", 0], [4.95, "That's the rep.", 0], [6.01, "By six, your manager needs your direction, not every detail, so share where you're heading and use their feedback to align before you fill in the rest.", 0]], "v": "k1", "cues": [0.01]}, "n_1_12": {"dur": 29.92, "text": "Your core rep this week is your why, and it takes about ten minutes. Picture the end of the season, name the one change you most want to have made, and write your intention in one sentence. If you have five more minutes, copy the Core 4 ratings you made earlier in this lesson into drill 1.2, so your Playbook has them too. Confirm your weekly hour and sign your commitment. Complete your core rep, then ask one person how it landed. Select Open your Lesson 1 pages to get started.", "sents": [[0.05, "Your core rep this week is your why, and it takes about ten minutes.", 0], [4.59, "Picture the end of the season, name the one change you most want to have made, and write your intention in one sentence.", 0], [11.99, "If you have five more minutes, copy the Core 4 ratings you made earlier in this lesson into drill 1.2, so your Playbook has them too.", 1], [20.25, "Confirm your weekly hour and sign your commitment.", 2], [23.31, "Complete your core rep, then ask one person how it landed.", 3], [26.99, "Select Open your Lesson 1 pages to get started.", 3]], "v": "k1", "cues": [0.05, 11.99, 20.25, 23.31]}, "n_1_13": {"dur": 10.48, "text": "Each lesson brings in an Athleader Pro, a leader who lives one part of this work. This time you'll hear from Tracey Newell, the Change Commander. Press Play to hear from her.", "sents": [[0.05, "Each lesson brings in an Athleader Pro, a leader who lives one part of this work.", 0], [5.51, "This time you'll hear from Tracey Newell, the Change Commander.", 1], [9.09, "Press Play to hear from her.", 1]], "v": "k1", "cues": [0.05, 5.51]}, "n_1_14": {"dur": 11.52, "text": "Now try Tracey's drill. It takes three minutes. Select Start the timer and work through each step as it lights up. When you're done or once you've planned when you'll run it, select the option that fits.", "sents": [[0.05, "Now try Tracey's drill.", 0], [1.79, "It takes three minutes.", 0], [3.33, "Select Start the timer and work through each step as it lights up.", 1], [7.27, "When you're done or once you've planned when you'll run it, select the option that fits.", 1]], "v": "v4l", "cues": [0.05, 3.33]}, "n_1_16_q0": {"dur": 8.48, "text": "A few questions to check the main ideas. First, which of these best describes conditioning? Choose one, then select Submit.", "sents": [[0, "A few questions to check the main ideas.", 0], [2.51, "First, which of these best describes conditioning?", 0], [6.29, "Choose one, then select Submit.", 0]], "v": "v4l", "cues": [0]}, "n_1_16_q1": {"dur": 3.36, "text": "In your operating system, what is the 90-Day Way?", "sents": [[0, "In your operating system, what is the 90-Day Way?", 0]], "v": "v4l", "cues": [0]}, "n_1_16_q2": {"dur": 6.4, "text": "A key supplier cancels an hour before your big meeting. Which response shows conditioned agility?", "sents": [[0, "A key supplier cancels an hour before your big meeting.", 0], [3.97, "Which response shows conditioned agility?", 0]], "v": "v4l", "cues": [0]}, "n_1_16_q3": {"dur": 4.64, "text": "Last one. Why does the First Read drill ask for your first reaction?", "sents": [[0.15, "Last one.", 0], [1.25, "Why does the First Read drill ask for your first reaction?", 0]], "v": "v4l", "cues": [0.15]}, "n_1_16_w0": {"dur": 9.04, "text": "Conditioning is what you can consistently access under pressure when there's no time to think. Knowledge is what you can recall when there is time.", "sents": [[0.03, "Conditioning is what you can consistently access under pressure when there's no time to think.", 0], [5.89, "Knowledge is what you can recall when there is time.", 0]], "v": "v4l", "cues": [0.03]}, "n_1_16_w1": {"dur": 12.8, "text": "The 90-Day Way is the execution loop: plan, execute, reflect, and reset every 90 days so your priorities turn into practice. Your M.V.P. Blueprint is the engine it runs.", "sents": [[0.03, "The 90-Day Way is the execution loop: plan, execute, reflect, and reset every 90 days so your priorities turn into practice.", 0], [9.49, "Your M.V.P. Blueprint is the engine it runs.", 0]], "v": "v4l", "cues": [0.03]}, "n_1_16_w2": {"dur": 8.0, "text": "When agility is conditioned, you don't need certainty to move. You decide on what you have and keep adjusting as things change.", "sents": [[0.03, "When agility is conditioned, you don't need certainty to move.", 0], [4.31, "You decide on what you have and keep adjusting as things change.", 0]], "v": "r3", "cues": [0.03]}, "n_1_16_w3": {"dur": 6.56, "text": "Your first read is a baseline. Every later lesson measures against it, and it stays private to you.", "sents": [[0.01, "Your first read is a baseline.", 0], [2.39, "Every later lesson measures against it, and it stays private to you.", 0]], "v": "v4l", "cues": [0.01]}, "n_1_17": {"dur": 38.24, "text": "Before you go, here's what to keep from this lesson. Conditioning is what you can consistently access under pressure, so this season is built on practice rather than more knowledge. Your five words are how you reset when the pressure hits. The Core 4 are what you condition. Your M.V.P. Blueprint drives them, and the 90-Day Way is the cycle that puts them into practice. Your why is the first rep. It's your core rep in the Playbook this week. Select Download my answers for a Word copy of everything you wrote in this lesson. If you'd like to go further, Chapter 4 of the book explains why conditioning is different from training.", "sents": [[0.05, "Before you go, here's what to keep from this lesson.", 0], [3.47, "Conditioning is what you can consistently access under pressure, so this season is built on practice rather than more knowledge.", 1], [11.19, "Your five words are how you reset when the pressure hits.", 1], [14.67, "The Core 4 are what you condition.", 2], [17.11, "Your M.V.P. Blueprint drives them, and the 90-Day Way is the cycle that puts them into practice.", 2], [23.37, "Your why is the first rep.", 3], [25.51, "It's your core rep in the Playbook this week.", 3], [27.09, "Select Download my answers for a Word copy of everything you wrote in this lesson.", 4], [32.61, "If you'd like to go further, Chapter 4 of the book explains why conditioning is different from training.", 4]], "v": "k1", "cues": [0.05, 3.47, 14.67, 23.37, 27.09]}, "n_1_18": {"dur": 14.16, "text": "That's Lesson 1 done. Way to go! You've entered the Arena. This week, complete your core rep, writing your why, and ask one person how it landed. Next time, in Lesson 2, you'll start on your Inner Blueprint.", "sents": [[0.05, "That's Lesson 1 done.", 0], [1.69, "Way to go!", 0], [2.97, "You've entered the Arena.", 0], [4.79, "This week, complete your core rep, writing your why, and ask one person how it landed.", 1], [10.31, "Next time, in Lesson 2, you'll start on your Inner Blueprint.", 1]], "v": "k1", "cues": [0.05, 4.79]}, "n_1_3": {"dur": 13.12, "text": "Now take one clean read of how you react, before you learn the rest of the system. This drill is short. Press Play. Melissa will pause partway through and ask what you notice. Type your answer, and the video will resume.", "sents": [[0.03, "Now take one clean read of how you react, before you learn the rest of the system.", 0], [4.87, "This drill is short.", 0], [6.15, "Press Play.", 1], [7.21, "Melissa will pause partway through and ask what you notice.", 1], [10.69, "Type your answer, and the video will resume.", 1]], "v": "k1", "cues": [0.03, 6.15]}, "n_1_4": {"dur": 32.16, "text": "Here's what you'll practice in this lesson. When something you were counting on falls through, you'll catch your first reaction before you act on it, then reset with five words of your own. You'll learn what this season conditions: Agility, Resilience, Alignment and Wellbeing. Melissa calls them the Core 4. You'll see how your operating system fits together, with the M.V.P. Blueprint as the engine and the 90-Day Way as the loop you run. And you'll write your why in one sentence in your Playbook. That's your core rep this week.", "sents": [[0, "Here's what you'll practice in this lesson.", 0], [2.35, "When something you were counting on falls through, you'll catch your first reaction before you act on it, then reset with five words of your own.", 1], [10.53, "You'll learn what this season conditions: Agility, Resilience, Alignment and Wellbeing.", 2], [16.71, "Melissa calls them the Core 4.", 2], [19.03, "You'll see how your operating system fits together, with the M.V.P. Blueprint as the engine and the 90-Day Way as the loop you run.", 3], [26.69, "And you'll write your why in one sentence in your Playbook.", 4], [30.61, "That's your core rep this week.", 4]], "v": "r3", "cues": [0, 2.35, 10.53, 19.03, 26.69]}, "n_1_7": {"dur": 11.92, "text": "Melissa mentioned your Athleader Playbook. Download it now, because every lesson uses it. It opens in a new tab. Save a copy somewhere you'll find it. If you already saved it during setup, you're all set.", "sents": [[0.03, "Melissa mentioned your Athleader Playbook.", 0], [2.39, "Download it now, because every lesson uses it.", 0], [5.79, "It opens in a new tab.", 1], [7.31, "Save a copy somewhere you'll find it.", 1], [9.27, "If you already saved it during setup, you're all set.", 1]], "v": "k1", "cues": [0.03, 5.79]}, "n_1_8": {"dur": 11.44, "text": "Agility, Resilience, Alignment and Wellbeing are what this season conditions. Select each one to hear what changes when it's conditioned. Open all four before you move on.", "sents": [[0, "Agility, Resilience, Alignment and Wellbeing are what this season conditions.", 0], [5.23, "Select each one to hear what changes when it's conditioned.", 1], [9.35, "Open all four before you move on.", 1]], "v": "r3", "cues": [0, 5.23]}, "n_1_8_agility": {"dur": 12.24, "text": "When agility is conditioned, you don't need certainty to move. You make the call and adjust as things change. When it isn't, you wait for certainty while everything keeps changing around you.", "sents": [[0.01, "When agility is conditioned, you don't need certainty to move.", 0], [4.43, "You make the call and adjust as things change.", 0], [7.55, "When it isn't, you wait for certainty while everything keeps changing around you.", 1]], "v": "v4l", "cues": [0.01, 7.55]}, "n_1_8_alignment": {"dur": 12.08, "text": "When alignment is conditioned, you know what matters most. You make the hard call and keep people moving in the same direction. When it isn't, everything feels urgent and people pull in different directions.", "sents": [[0.01, "When alignment is conditioned, you know what matters most.", 0], [3.93, "You make the hard call and keep people moving in the same direction.", 0], [7.71, "When it isn't, everything feels urgent and people pull in different directions.", 1]], "v": "k1", "cues": [0.01, 7.71]}, "n_1_8_resilience": {"dur": 10.24, "text": "When resilience is conditioned, a setback becomes a lesson you can use, and you're ready for the next play. When it isn't, one hard moment follows you into the next one.", "sents": [[0.07, "When resilience is conditioned, a setback becomes a lesson you can use, and you're ready for the next play.", 0], [6.47, "When it isn't, one hard moment follows you into the next one.", 1]], "v": "r3", "cues": [0.07, 6.47]}, "n_1_8_wellbeing": {"dur": 12.08, "text": "When wellbeing is conditioned, you manage your energy and your boundaries, so your best is still there when demand rises. When it isn't, you're leading on fumes by Wednesday, and everyone can tell.", "sents": [[0.01, "When wellbeing is conditioned, you manage your energy and your boundaries, so your best is still there when demand rises.", 0], [7.77, "When it isn't, you're leading on fumes by Wednesday, and everyone can tell.", 1]], "v": "v4l", "cues": [0.01, 7.77]}, "n_1_8b": {"dur": 23.04, "text": "Before you go on, set your starting line. Rate yourself from one to five on each of the Core 4, as you lead today. One means rarely, five means consistently. Be honest, because only you see this. In Lesson 6 you'll see these numbers again, next to your new ratings, so you can see how far you've moved. Select Next when all four are rated.", "sents": [[0.01, "Before you go on, set your starting line.", 0], [3.01, "Rate yourself from one to five on each of the Core 4, as you lead today.", 1], [7.71, "One means rarely, five means consistently.", 1], [11.39, "Be honest, because only you see this.", 1], [14.29, "In Lesson 6 you'll see these numbers again, next to your new ratings, so you can see how far you've moved.", 2], [20.51, "Select Next when all four are rated.", 2]], "v": "v4l", "cues": [0.01, 3.01, 14.29]}, "n_1_9": {"dur": 43.52, "text": "Your M.V.P. Blueprint is the engine. It's your mission, vision, and purpose, written down, with your values underneath all three. Most leaders have a purpose, but fewer than one in five can state theirs in a sentence. The 90-Day Way is the loop in which you run that engine. Your 90-day plan starts with your mission, vision, and purpose, and turns them into two or three clear goals for your work and for your life outside it. You plan, carry out the plan, reflect every week, then reset and start the next season. The Blueprint tells you where you're going and why it matters. The 90-Day Way is how you get a little closer to it every week. Select any step in the loop to see what you do there.", "sents": [[0.01, "Your M.V.P. Blueprint is the engine.", 0], [2.73, "It's your mission, vision, and purpose, written down, with your values underneath all three.", 0], [8.61, "Most leaders have a purpose, but fewer than one in five can state theirs in a sentence.", 1], [14.33, "The 90-Day Way is the loop in which you run that engine.", 2], [18.17, "Your 90-day plan starts with your mission, vision, and purpose, and turns them into two or three clear goals for your work and for your life outside it.", 2], [27.21, "You plan, carry out the plan, reflect every week, then reset and start the next season.", 2], [33.29, "The Blueprint tells you where you're going and why it matters.", 3], [36.75, "The 90-Day Way is how you get a little closer to it every week.", 3], [40.81, "Select any step in the loop to see what you do there.", 3]], "v": "k1", "cues": [0.01, 8.61, 14.33, 33.29]}, "n_1_R": {"dur": 54.0, "text": "Before your first Moment, here's one tool you'll use all season. It's called the Foundation Reset, and it comes from Melissa's book. Under pressure, your brain's alarm, the amygdala, fires faster than the part that plans, the prefrontal cortex. Your five words tell the alarm to stand down and bring your thinking brain back online. Melissa used it in a hotel hallway, less than two days before her biggest summit, as the world shut down for the COVID-19 pandemic. Five words: “I'm not in danger, deciding.” Two options: cancel or pivot? One default: “We pivot, now.” Thirty-eight hours later, her summit went live as one of the first global virtual leadership events. Now write your own five words. Use one of Melissa's to start, or write words that would steady you. Select Save, and you'll see them again in every check-in.", "sents": [[0, "Before your first Moment, here's one tool you'll use all season.", 0], [4.45, "It's called the Foundation Reset, and it comes from Melissa's book.", 0], [8.49, "Under pressure, your brain's alarm, the amygdala, fires faster than the part that plans, the prefrontal cortex.", 1], [15.83, "Your five words tell the alarm to stand down and bring your thinking brain back online.", 1], [21.27, "Melissa used it in a hotel hallway, less than two days before her biggest summit, as the world shut down for the COVID-19 pandemic.", 2], [30.65, "Five words: “I'm not in danger, deciding.”", 2], [33.19, "Two options: cancel or pivot?", 2], [34.99, "One default: “We pivot, now.”", 2], [37.37, "Thirty-eight hours later, her summit went live as one of the first global virtual leadership events.", 2], [45.21, "Now write your own five words.", 3], [47.17, "Use one of Melissa's to start, or write words that would steady you.", 3], [50.87, "Select Save, and you'll see them again in every check-in.", 3]], "v": "p1", "cues": [0, 8.49, 21.27, 45.21]}, "r2_code_pulse": {"dur": 7.36, "text": "Type the code from the last page of the Pulse Check, then select Submit. A quick knowledge check comes next, then your recap.", "sents": [[0.01, "Type the code from the last page of the Pulse Check, then select Submit.", 0], [4.23, "A quick knowledge check comes next, then your recap.", 0]], "v": "r3", "cues": [0.01]}, "r2_form_pulse": {"dur": 8.96, "text": "Answer the five questions, then select Submit. Your code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0, "Answer the five questions, then select Submit.", 0], [3.25, "Your code appears on the last page.", 0], [5.45, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0]}, "r2_pulse": {"dur": 21.36, "text": "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season. It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks. It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing. Select Next, and it opens right here.", "sents": [[0.01, "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season.", 0], [6.57, "It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks.", 1], [12.25, "It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing.", 2], [18.83, "Select Next, and it opens right here.", 2]], "v": "k1", "cues": [0.01, 6.57, 12.25]}};
